1	import { timestampDate } from "@bufbuild/protobuf/wkt";
2	import { Code, ConnectError, createClient, type Interceptor } from "@connectrpc/connect";
3	import { createConnectTransport } from "@connectrpc/connect-web";
4	import { getAccessToken, hasStoredToken, isTokenExpired, REQUEST_TOKEN_EXPIRY_BUFFER_MS, setAccessToken } from "./auth-state";
5	import { AIService } from "./types/proto/api/v1/ai_service_pb";
6	import { AttachmentService } from "./types/proto/api/v1/attachment_service_pb";
7	import { AuthService } from "./types/proto/api/v1/auth_service_pb";
8	import { IdentityProviderService } from "./types/proto/api/v1/idp_service_pb";
9	import { InstanceService } from "./types/proto/api/v1/instance_service_pb";
10	import { MemoService } from "./types/proto/api/v1/memo_service_pb";
11	import { ShortcutService } from "./types/proto/api/v1/shortcut_service_pb";
12	import { UserService } from "./types/proto/api/v1/user_service_pb";
13	import { redirectOnAuthFailure } from "./utils/auth-redirect";
14	
15	interface RequestWithHeader {
16	  header: Headers;
17	}
18	
19	// ============================================================================
20	// Constants
21	// ============================================================================
22	
23	const RETRY_HEADER = "X-Retry";
24	const RETRY_HEADER_VALUE = "true";
25	
26	// ============================================================================
27	// Token Refresh State Management
28	// ============================================================================
29	
30	const createTokenRefreshManager = () => {
31	  let isRefreshing = false;
32	  let refreshPromise: Promise<void> | null = null;
33	
34	  return {
35	    async refresh(refreshFn: () => Promise<void>): Promise<void> {
36	      if (isRefreshing && refreshPromise) {
37	        return refreshPromise;
38	      }
39	
40	      isRefreshing = true;
41	      refreshPromise = refreshFn().finally(() => {
42	        isRefreshing = false;
43	        refreshPromise = null;
44	      });
45	
46	      return refreshPromise;
47	    },
48	  };
49	};
50	
51	const tokenRefreshManager = createTokenRefreshManager();
52	
53	// ============================================================================
54	// Token Refresh
55	// ============================================================================
56	
57	const fetchWithCredentials: typeof globalThis.fetch = (input, init) => {
58	  return globalThis.fetch(input, {
59	    ...init,
60	    credentials: "include",
61	  });
62	};
63	
64	// Separate transport without auth interceptor to prevent recursion
65	const refreshTransport = createConnectTransport({
66	  baseUrl: window.location.origin,
67	  useBinaryFormat: true,
68	  fetch: fetchWithCredentials,
69	  interceptors: [],
70	});
71	
72	const refreshAuthClient = createClient(AuthService, refreshTransport);
73	
74	async function doRefreshAccessToken(): Promise<void> {
75	  const response = await refreshAuthClient.refreshToken({});
76	
77	  if (!response.accessToken) {
78	    throw new ConnectError("Refresh token response missing access token", Code.Internal);
79	  }
80	
81	  const expiresAt = response.expiresAt ? timestampDate(response.expiresAt) : undefined;
82	  setAccessToken(response.accessToken, expiresAt);
83	}
84	
85	// All callers go through the manager to deduplicate concurrent refresh requests.
86	// This prevents race conditions between useTokenRefreshOnFocus (proactive refresh
87	// on tab focus) and the auth interceptor (reactive refresh on 401), which could
88	// otherwise send duplicate requests that conflict with server-side token rotation.
89	export async function refreshAccessToken(): Promise<void> {
90	  return tokenRefreshManager.refresh(doRefreshAccessToken);
91	}
92	
93	// ============================================================================
94	// Authentication Interceptor Helpers
95	// ============================================================================
96	
97	function setAuthorizationHeader(req: RequestWithHeader, token: string | null) {
98	  if (!token) return;
99	  req.header.set("Authorization", `Bearer ${token}`);
100	}
101	
102	function shouldHandleUnauthenticatedRetry(error: unknown, isRetryAttempt: boolean): boolean {
103	  if (!(error instanceof ConnectError)) {
104	    return false;
105	  }
106	  if (error.code !== Code.Unauthenticated) {
107	    return false;
108	  }
109	  if (isRetryAttempt) {
110	    return false;
111	  }
112	  return true;
113	}
114	
115	async function refreshAndGetAccessToken(): Promise<string> {
116	  await refreshAccessToken();
117	  const token = getAccessToken();
118	  if (!token) {
119	    throw new ConnectError("Token refresh succeeded but no token available", Code.Internal);
120	  }
121	  return token;
122	}
123	
124	export async function getRequestToken(): Promise<string | null> {
125	  let token = getAccessToken();
126	  if (!token) {
127	    if (!hasStoredToken()) return null;
128	    try {
129	      token = await refreshAndGetAccessToken();
130	    } catch {
131	      return null;
132	    }
133	    return token;
134	  }
135	
136	  // Preflight refresh: avoid sending requests with expired access tokens.
137	  // This is especially important for public endpoints (e.g. ListMemos), where
138	  // an expired token could otherwise be treated as anonymous and return
139	  // guest-scoped data before the reactive 401 refresh path runs.
140	  if (isTokenExpired(REQUEST_TOKEN_EXPIRY_BUFFER_MS)) {
141	    try {
142	      token = await refreshAndGetAccessToken();
143	    } catch {
144	      // Keep existing reactive 401 flow as fallback.
145	      // Protected methods still trigger refresh/redirect in the catch block below.
146	    }
147	  }
148	
149	  return token;
150	}
151	
152	// ============================================================================
153	// Authentication Interceptor
154	// ============================================================================
155	
156	const authInterceptor: Interceptor = (next) => async (req) => {
157	  const isRetryAttempt = req.header.get(RETRY_HEADER) === RETRY_HEADER_VALUE;
158	  const token = await getRequestToken();
159	  setAuthorizationHeader(req, token);
160	
161	  try {
162	    return await next(req);
163	  } catch (error) {
164	    if (!shouldHandleUnauthenticatedRetry(error, isRetryAttempt)) {
165	      throw error;
166	    }
167	
168	    try {
169	      const newToken = await refreshAndGetAccessToken();
170	      setAuthorizationHeader(req, newToken);
171	      req.header.set(RETRY_HEADER, RETRY_HEADER_VALUE);
172	      return await next(req);
173	    } catch (refreshError) {
174	      redirectOnAuthFailure();
175	      throw refreshError;
176	    }
177	  }
178	};
179	
180	// ============================================================================
181	// Transport & Service Clients
182	// ============================================================================
183	
184	const transport = createConnectTransport({
185	  baseUrl: window.location.origin,
186	  useBinaryFormat: true,
187	  fetch: fetchWithCredentials,
188	  interceptors: [authInterceptor],
189	});
190	
191	// Core service clients
192	export const instanceServiceClient = createClient(InstanceService, transport);
193	export const authServiceClient = createClient(AuthService, transport);
194	export const userServiceClient = createClient(UserService, transport);
195	
196	// Content service clients
197	export const memoServiceClient = createClient(MemoService, transport);
198	export const attachmentServiceClient = createClient(AttachmentService, transport);
199	export const aiServiceClient = createClient(AIService, transport);
200	export const shortcutServiceClient = createClient(ShortcutService, transport);
201	
202	// Configuration service clients
203	export const identityProviderServiceClient = createClient(IdentityProviderService, transport);
204

1	import { create } from "@bufbuild/protobuf";
2	import { FieldMaskSchema } from "@bufbuild/protobuf/wkt";
3	import type { InfiniteData } from "@tanstack/react-query";
4	import { useInfiniteQuery, useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
5	import { memoServiceClient } from "@/connect";
6	import { userKeys } from "@/hooks/useUserQueries";
7	import { DEFAULT_LIST_MEMOS_PAGE_SIZE } from "@/lib/constants";
8	import type { ListMemosRequest, ListMemosResponse, Memo } from "@/types/proto/api/v1/memo_service_pb";
9	import { ListMemoCommentsRequestSchema, ListMemosRequestSchema, MemoSchema } from "@/types/proto/api/v1/memo_service_pb";
10	
11	// Query keys factory for consistent cache management
12	export const memoKeys = {
13	  all: ["memos"] as const,
14	  lists: () => [...memoKeys.all, "list"] as const,
15	  list: (filters: Partial<ListMemosRequest>) => [...memoKeys.lists(), filters] as const,
16	  details: () => [...memoKeys.all, "detail"] as const,
17	  detail: (name: string) => [...memoKeys.details(), name] as const,
18	  comments: (name: string) => [...memoKeys.all, "comments", name] as const,
19	  linkMetadata: (url: string) => [...memoKeys.all, "linkMetadata", url] as const,
20	};
21	
22	type MemoPatch = Partial<Memo> & Pick<Memo, "name">;
23	type MemoCollectionQueryData = ListMemosResponse | InfiniteData<ListMemosResponse>;
24	
25	function isMemoListResponse(data: unknown): data is ListMemosResponse {
26	  return typeof data === "object" && data !== null && Array.isArray((data as { memos?: unknown }).memos);
27	}
28	
29	function isInfiniteMemoListData(data: unknown): data is InfiniteData<ListMemosResponse> {
30	  return typeof data === "object" && data !== null && Array.isArray((data as { pages?: unknown }).pages);
31	}
32	
33	function patchMemoListResponse(response: ListMemosResponse, update: MemoPatch): ListMemosResponse {
34	  let changed = false;
35	  const memos = response.memos.map((memo) => {
36	    if (memo.name !== update.name) {
37	      return memo;
38	    }
39	
40	    changed = true;
41	    return { ...memo, ...update };
42	  });
43	
44	  return changed ? { ...response, memos } : response;
45	}
46	
47	function patchMemoListQueryData<T>(data: T | undefined, update: MemoPatch): T | undefined {
48	  if (!data) {
49	    return data;
50	  }
51	
52	  if (isMemoListResponse(data)) {
53	    return patchMemoListResponse(data, update) as T;
54	  }
55	
56	  if (isInfiniteMemoListData(data)) {
57	    let changed = false;
58	    const pages = data.pages.map((page) => {
59	      const patchedPage = patchMemoListResponse(page, update);
60	      if (patchedPage !== page) {
61	        changed = true;
62	      }
63	      return patchedPage;
64	    });
65	
66	    return (changed ? { ...data, pages } : data) as T;
67	  }
68	
69	  return data;
70	}
71	
72	function findMemoInListResponse(response: ListMemosResponse, name: string): Memo | undefined {
73	  return response.memos.find((memo) => memo.name === name);
74	}
75	
76	function findMemoInQueryData(data: unknown, name: string): Memo | undefined {
77	  if (!data) {
78	    return undefined;
79	  }
80	
81	  if (isMemoListResponse(data)) {
82	    return findMemoInListResponse(data, name);
83	  }
84	
85	  if (isInfiniteMemoListData(data)) {
86	    for (const page of data.pages) {
87	      const memo = findMemoInListResponse(page, name);
88	      if (memo) {
89	        return memo;
90	      }
91	    }
92	  }
93	
94	  return undefined;
95	}
96	
97	function findMemoInCollectionQueries(queryClient: ReturnType<typeof useQueryClient>, name: string): Memo | undefined {
98	  for (const [, data] of queryClient.getQueriesData<unknown>({ queryKey: memoKeys.all })) {
99	    const memo = findMemoInQueryData(data, name);
100	    if (memo) {
101	      return memo;
102	    }
103	  }
104	
105	  return undefined;
106	}
107	
108	function patchMemoInCollectionQueries(queryClient: ReturnType<typeof useQueryClient>, update: MemoPatch) {
109	  queryClient.setQueriesData<MemoCollectionQueryData>({ queryKey: memoKeys.all }, (data) => patchMemoListQueryData(data, update));
110	}
111	
112	export function useMemos(request: Partial<ListMemosRequest> = {}) {
113	  return useQuery({
114	    queryKey: memoKeys.list(request),
115	    queryFn: async () => {
116	      const response = await memoServiceClient.listMemos(create(ListMemosRequestSchema, request as Record<string, unknown>));
117	      return response;
118	    },
119	  });
120	}
121	
122	export function useInfiniteMemos(request: Partial<ListMemosRequest> = {}, options?: { enabled?: boolean }) {
123	  return useInfiniteQuery({
124	    queryKey: memoKeys.list(request),
125	    queryFn: async ({ pageParam }) => {
126	      const response = await memoServiceClient.listMemos(
127	        create(ListMemosRequestSchema, {
128	          ...request,
129	          pageToken: pageParam || "",
130	        } as Record<string, unknown>),
131	      );
132	      return response;
133	    },
134	    initialPageParam: "",
135	    getNextPageParam: (lastPage) => lastPage.nextPageToken || undefined,
136	    staleTime: 1000 * 60,
137	    gcTime: 1000 * 60 * 5,
138	    enabled: options?.enabled ?? true,
139	  });
140	}
141	
142	export function useMemo(name: string, options?: { enabled?: boolean }) {
143	  return useQuery({
144	    queryKey: memoKeys.detail(name),
145	    queryFn: async () => {
146	      const memo = await memoServiceClient.getMemo({ name });
147	      return memo;
148	    },
149	    enabled: options?.enabled ?? true,
150	    staleTime: 1000 * 10, // 10 seconds - reduced to prevent stale data in collaborative editing
151	  });
152	}
153	
154	function isHTTPURL(url: string): boolean {
155	  try {
156	    const parsed = new URL(url);
157	    return parsed.protocol === "http:" || parsed.protocol === "https:";
158	  } catch {
159	    return false;
160	  }
161	}
162	
163	export function useLinkMetadata(url: string, options?: { enabled?: boolean }) {
164	  const trimmedUrl = url.trim();
165	
166	  return useQuery({
167	    queryKey: memoKeys.linkMetadata(trimmedUrl),
168	    queryFn: async () => {
169	      const metadata = await memoServiceClient.getLinkMetadata({ url: trimmedUrl });
170	      return metadata;
171	    },
172	    enabled: (options?.enabled ?? true) && isHTTPURL(trimmedUrl),
173	    staleTime: 1000 * 60 * 60 * 24,
174	    gcTime: 1000 * 60 * 60 * 24,
175	  });
176	}
177	
178	export function useCreateMemo() {
179	  const queryClient = useQueryClient();
180	
181	  return useMutation({
182	    mutationFn: async (memoToCreate: Memo) => {
183	      const memo = await memoServiceClient.createMemo({ memo: memoToCreate });
184	      return memo;
185	    },
186	    onSuccess: (newMemo) => {
187	      // Invalidate memo lists to refetch
188	      queryClient.invalidateQueries({ queryKey: memoKeys.lists() });
189	      // Add new memo to cache
190	      queryClient.setQueryData(memoKeys.detail(newMemo.name), newMemo);
191	      // Invalidate user stats
192	      queryClient.invalidateQueries({ queryKey: userKeys.stats() });
193	    },
194	  });
195	}
196	
197	export function useUpdateMemo() {
198	  const queryClient = useQueryClient();
199	
200	  return useMutation({
201	    mutationFn: async ({ update, updateMask }: { update: Partial<Memo>; updateMask: string[] }) => {
202	      const memo = await memoServiceClient.updateMemo({
203	        memo: create(MemoSchema, update as Record<string, unknown>),
204	        updateMask: create(FieldMaskSchema, { paths: updateMask }),
205	      });
206	      return memo;
207	    },
208	    onMutate: async ({ update }) => {
209	      if (!update.name) {
210	        return { previousMemo: undefined };
211	      }
212	
213	      // Cancel outgoing refetches to prevent race conditions
214	      await queryClient.cancelQueries({ queryKey: memoKeys.all });
215	
216	      // Snapshot previous value for rollback on error
217	      const previousMemo =
218	        queryClient.getQueryData<Memo>(memoKeys.detail(update.name)) || findMemoInCollectionQueries(queryClient, update.name);
219	      const memoPatch: MemoPatch = { ...update, name: update.name };
220	
221	      // Optimistically update the cache
222	      if (previousMemo) {
223	        queryClient.setQueryData(memoKeys.detail(update.name), { ...previousMemo, ...memoPatch });
224	      }
225	      patchMemoInCollectionQueries(queryClient, memoPatch);
226	
227	      return { previousMemo };
228	    },
229	    onError: (_err, { update }, context) => {
230	      // Rollback on error
231	      if (context?.previousMemo && update.name) {
232	        queryClient.setQueryData(memoKeys.detail(update.name), context.previousMemo);
233	        patchMemoInCollectionQueries(queryClient, context.previousMemo);
234	      } else {
235	        queryClient.invalidateQueries({ queryKey: memoKeys.all });
236	      }
237	    },
238	    onSuccess: (updatedMemo) => {
239	      // Update cache with server response
240	      queryClient.setQueryData(memoKeys.detail(updatedMemo.name), updatedMemo);
241	      patchMemoInCollectionQueries(queryClient, updatedMemo);
242	      // Invalidate lists to refresh
243	      queryClient.invalidateQueries({ queryKey: memoKeys.lists() });
244	      if (updatedMemo.parent) {
245	        queryClient.invalidateQueries({ queryKey: memoKeys.comments(updatedMemo.parent) });
246	      }
247	      // Invalidate user stats
248	      queryClient.invalidateQueries({ queryKey: userKeys.stats() });
249	    },
250	  });
251	}
252	
253	export function useDeleteMemo() {
254	  const queryClient = useQueryClient();
255	
256	  return useMutation({
257	    mutationFn: async (name: string) => {
258	      await memoServiceClient.deleteMemo({ name });
259	      return name;
260	    },
261	    onSuccess: (name) => {
262	      // Remove from cache
263	      queryClient.removeQueries({ queryKey: memoKeys.detail(name) });
264	      // Invalidate lists
265	      queryClient.invalidateQueries({ queryKey: memoKeys.lists() });
266	      // Invalidate user stats
267	      queryClient.invalidateQueries({ queryKey: userKeys.stats() });
268	    },
269	  });
270	}
271	
272	export function useMemoComments(name: string, options?: { enabled?: boolean; pageSize?: number }) {
273	  return useQuery({
274	    queryKey: [...memoKeys.comments(name), options?.pageSize ?? 0],
275	    queryFn: async () => {
276	      const response = await memoServiceClient.listMemoComments(
277	        create(ListMemoCommentsRequestSchema, {
278	          name,
279	          pageSize: options?.pageSize ?? 0,
280	        }),
281	      );
282	      return response;
283	    },
284	    enabled: options?.enabled ?? true,
285	    staleTime: 1000 * 60, // 1 minute
286	  });
287	}
288	
289	// useInfiniteMemoComments paginates through every comment via nextPageToken, instead of
290	// stopping at the server's default page size (the cause of comments being truncated to 10).
291	export function useInfiniteMemoComments(name: string, options?: { enabled?: boolean; pageSize?: number }) {
292	  const pageSize = options?.pageSize ?? DEFAULT_LIST_MEMOS_PAGE_SIZE;
293	  return useInfiniteQuery({
294	    queryKey: [...memoKeys.comments(name), "infinite", pageSize],
295	    queryFn: async ({ pageParam }) => {
296	      const response = await memoServiceClient.listMemoComments(
297	        create(ListMemoCommentsRequestSchema, {
298	          name,
299	          pageSize,
300	          pageToken: pageParam || "",
301	        }),
302	      );
303	      return response;
304	    },
305	    initialPageParam: "",
306	    getNextPageParam: (lastPage) => lastPage.nextPageToken || undefined,
307	    select: (data) => data.pages.flatMap((page) => page.memos),
308	    enabled: options?.enabled ?? true,
309	    staleTime: 1000 * 60, // 1 minute
310	  });
311	}
