169	func normalizeInstanceURL(instanceURL string) (string, error) {
170		instanceURL = strings.TrimRight(instanceURL, "/")
171		if instanceURL == "" {
172			return "", echo.NewHTTPError(http.StatusNotFound, "instance URL is not configured")
173		}
174		return instanceURL, nil
175	}
